import { create } from "zustand";
import { persist } from "zustand/middleware";
import { defaultAddresses, getProduct, promoCodes } from "../data/mock";
export const DELIVERY_FEE = 12e3;
export const FREE_DELIVERY_FROM = 15e4;
export const useShop = create()(
  persist(
    (set, get) => ({
      cart: [],
      orders: [],
      addresses: defaultAddresses,
      user: null,
      favorites: [],
      promo: null,
      toasts: [],
      addToCart: (productId, qty = 1) => {
        const product = getProduct(productId);
        if (!product) return;
        const amount = Math.max(1, Number(qty) || 1);
        const cart = get().cart.map((item) => ({ ...item }));
        const existing = cart.find((c) => c.productId === productId);
        if (existing) existing.qty = Math.min(existing.qty + amount, product.stock);
        else cart.push({ productId, qty: Math.min(amount, product.stock) });
        set({ cart });
        get().pushToast(`${product.name} savatga qo'shildi`, "success");
      },
      removeFromCart: (productId) => set({ cart: get().cart.filter((c) => c.productId !== productId) }),
      setQty: (productId, qty) => {
        const product = getProduct(productId);
        if (!product) return;
        if (qty <= 0) {
          get().removeFromCart(productId);
          return;
        }
        set({ cart: get().cart.map((c) => c.productId === productId ? { ...c, qty: Math.min(qty, product.stock) } : c) });
      },
      clearCart: () => set({ cart: [], promo: null }),
      toggleFavorite: (productId) => {
        const has = get().favorites.includes(productId);
        set({ favorites: has ? get().favorites.filter((id) => id !== productId) : [...get().favorites, productId] });
        const product = getProduct(productId);
        if (product) get().pushToast(has ? "Sevimlilardan olib tashlandi" : `${product.name} sevimlilarga qo'shildi`, "success");
      },
      applyPromo: (code) => {
        const clean = code.trim().toUpperCase();
        const found = promoCodes.find((p) => p.code === clean);
        if (!found) return { ok: false, message: "Promo-kod topilmadi" };
        const subtotal = get().cart.reduce((sum, item) => {
          const product = getProduct(item.productId);
          return sum + (product ? product.price * item.qty : 0);
        }, 0);
        if (subtotal < found.min) {
          return { ok: false, message: `Minimal buyurtma: ${new Intl.NumberFormat("ru-RU").format(found.min)} so'm` };
        }
        set({ promo: { code: found.code, percent: found.percent ?? 0, amount: found.amount ?? 0, freeShip: found.code === "FREESHIP" } });
        get().pushToast(`Promo-kod qo'llanildi: ${found.code}`, "success");
        return { ok: true, message: "Promo-kod qo'llanildi" };
      },
      removePromo: () => set({ promo: null }),
      placeOrder: (input) => {
        const cart = get().cart;
        const items = cart.map((item) => {
          const product = getProduct(item.productId);
          if (!product) return null;
          return {
            productId: product.id,
            name: product.name,
            price: product.price,
            qty: item.qty,
            emoji: product.emoji,
            unit: product.unit
          };
        }).filter(Boolean);
        const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
        const promo = get().promo;
        const discount = promo ? (promo.amount ? Math.min(promo.amount, subtotal) : Math.round(subtotal * promo.percent / 100)) : 0;
        const delivery = promo?.freeShip || subtotal >= FREE_DELIVERY_FROM ? 0 : DELIVERY_FEE;
        const total = Math.max(0, subtotal - discount + delivery);
        const id = `MS-${Math.floor(20500 + Math.random() * 8e3)}`;
        const order = {
          id,
          date: (/* @__PURE__ */ new Date()).toLocaleString("ru-RU", { dateStyle: "short", timeStyle: "short" }),
          items,
          subtotal,
          delivery,
          discount,
          total,
          status: "confirmed",
          address: input.address,
          payment: input.payment,
          slot: input.slot,
          note: input.note ?? "",
          courier: "Jasur Toshmatov",
          eta: "35 daqiqa"
        };
        set({ orders: [order, ...get().orders], cart: [], promo: null });
        return id;
      },
      addAddress: (address) => {
        const list = get().addresses;
        const newAddress = { ...address, id: `a${Date.now()}`, isDefault: list.length === 0 || address.isDefault };
        set({ addresses: newAddress.isDefault ? [...list.map((a) => ({ ...a, isDefault: false })), newAddress] : [...list, newAddress] });
        get().pushToast("Manzil qo'shildi", "success");
      },
      removeAddress: (id) => {
        const list = get().addresses.filter((a) => a.id !== id);
        if (list.length && !list.some((a) => a.isDefault)) list[0].isDefault = true;
        set({ addresses: list });
        get().pushToast("Manzil o'chirildi", "info");
      },
      setDefaultAddress: (id) => {
        set({ addresses: get().addresses.map((a) => ({ ...a, isDefault: a.id === id })) });
      },
      login: (phone, name = "Aziz Karimov") => {
        set({ user: { name, phone, email: `${phone.replace(/\D/g, "").slice(-9)}@maxshop.uz` } });
        get().pushToast(`Xush kelibsiz, ${name.split(" ")[0]}!`, "success");
      },
      register: (name, phone, email) => {
        set({ user: { name, phone, email } });
        get().pushToast("Hisob muvaffaqiyatli yaratildi", "success");
      },
      updateUser: (patch) => {
        const current = get().user;
        if (!current) return;
        set({ user: { ...current, ...patch } });
        get().pushToast("Profil yangilandi", "success");
      },
      logout: () => {
        set({ user: null });
        get().pushToast("Tizimdan chiqdingiz", "info");
      },
      pushToast: (message, type = "success") => {
        const id = Date.now() + Math.random();
        set({ toasts: [...get().toasts, { id, message, type }] });
        setTimeout(() => get().dismissToast(id), 3200);
      },
      dismissToast: (id) => set({ toasts: get().toasts.filter((t) => t.id !== id) })
    }),
    {
      name: "maxshop-web-v2",
      partialize: (state) => ({
        cart: state.cart,
        orders: state.orders,
        addresses: state.addresses,
        user: state.user,
        favorites: state.favorites,
        promo: state.promo
      })
    }
  )
);
export const cartDetails = (cart, promo) => {
  const subtotal = cart.reduce((sum, item) => {
    const product = getProduct(item.productId);
    return sum + (product ? product.price * item.qty : 0);
  }, 0);
  const discount = promo ? (promo.amount ? Math.min(promo.amount, subtotal) : Math.round(subtotal * promo.percent / 100)) : 0;
  const delivery = subtotal === 0 || promo?.freeShip || subtotal >= FREE_DELIVERY_FROM ? 0 : DELIVERY_FEE;
  return { subtotal, discount, delivery, total: Math.max(0, subtotal - discount + delivery) };
};
export const cartCount = (cart) => cart.reduce((sum, item) => sum + item.qty, 0);
export const productById = (id) => getProduct(id);
